// ResponseHeartbeatEvent Keepalive event emitted on a fixed cadence during streaming.
//
// Lets consumers detect stalled producers via missed-interval
// timing. Cadence is set by the server (15 seconds at the time of
// writing).
//
// Per `designs/SERVER_HARNESS_CONTRACT.md` §Heartbeats, the
// event MAY carry timing metadata so consumers can do richer
// dead-detection than "did anything arrive":
//
//   - `server_time` is the producer's wall-clock at emission,
//     letting consumers detect clock drift between producer and
//     consumer.
//   - `last_event_seq` is the `sequence_number` of the most
//     recent NON-heartbeat event (or `None` when this is the
//     first heartbeat before any user-visible event), letting
//     consumers detect dropped events on reconnect.
//
// Both fields are optional on the wire (`None` round-trips as
// omitted) so older AP→harness pairs that pre-date the field
// addition still parse cleanly.
//
// Wire type: "response.heartbeat".
type ResponseHeartbeatEvent struct {
	// LastEventSeq Sequence number of the last non- heartbeat event seen on the same stream, e.g. `42`. `None` before any user-visible event has fired (first heartbeat of the turn, before deltas land), or when the producer chose not to populate it.
	LastEventSeq   *int `json:"last_event_seq,omitempty"`
	SequenceNumber *int `json:"sequence_number,omitempty"`

	// ServerTime ISO 8601 UTC timestamp at emission, e.g. `"2026-04-27T15:30:00Z"`. `None` when the producer chose not to populate it (legacy emitters).
	ServerTime *string `json:"server_time,omitempty"`

	// Type Always `"response.heartbeat"`.
	Type ResponseHeartbeatEventType `json:"type"`
}

// ResponseHeartbeatEventType Always `"response.heartbeat"`.
type ResponseHeartbeatEventType string

